using Scripts.Level;
using System.Collections;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using System.Collections.Generic;
[InitializeOnLoad] public static class DeveloperOverlayValidation{
 const string Out="output/developer-overlay/";static bool running;static double started;
 static DeveloperOverlayValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("DEVELOPER_OVERLAY_QA",false)){SessionState.SetBool("DEVELOPER_OVERLAY_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");File.WriteAllText(Out+"validation.txt","");UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Gameplay.unity");SessionState.SetBool("DEVELOPER_OVERLAY_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("DEVELOPER_OVERLAY_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;started=EditorApplication.timeSinceStartup;GameManager.single.StartCoroutine(Run());}if(running&&EditorApplication.timeSinceStartup-started>180){Check(false,"timeout");EditorApplication.isPlaying=false;}}
 static void Check(bool ok,string s)=>File.AppendAllText(Out+"validation.txt",(ok?"PASS ":"FAIL ")+s+"\n");
 static IEnumerator Run(){var intro=Object.FindAnyObjectByType<CursedBookIntro>(FindObjectsInactive.Include);while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(1);var gc=GameplayCanvas.single;gc.CancelInvoke("TryShowingXpBoosterNotification");if(gc.xpBoosterNotification)gc.xpBoosterNotification.SetActive(false);if(gc.dailyCherriesPop)gc.dailyCherriesPop.SetActive(false);TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();var ui=gc.homeUI.settingsUI;
 var debug=DebugMenu.Instance;debug.Open();var view=debug.View;
 foreach(var size in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){StorybookEquipmentValidation.Resolution(size.x,size.y);view.SetExpanded(true);yield return new WaitForSecondsRealtime(.4f);var corners=new Vector3[4];view.panel.GetWorldCorners(corners);Check(corners[0].x>=0&&corners[0].y>=0&&corners[2].x<=Screen.width&&corners[2].y<=Screen.height,"Panel within screen "+size);yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+"expanded-"+size.x+"x"+size.y+".png",t.EncodeToPNG());Object.Destroy(t);view.fold.onClick.Invoke();yield return null;Check(!view.body.activeSelf&&view.panel.rect.height==52,"Collapse removes body "+size);var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=new Vector2(Screen.width/2,Screen.height/2)},hits);Check(hits.TrueForAll(h=>!h.gameObject.GetComponentInParent<DeveloperOverlayUI>()),"Collapsed overlay does not block game "+size);}
 view.SetExpanded(true);var gm=GameManager.single;
 int oldLevel=gm.playerLevel,oldStat=gm.statPoints,oldSkill=gm.skillPoints;
 view.levels.onClick.Invoke();yield return null;
 Check(gm.playerLevel==oldLevel+10&&gm.statPoints==oldStat+10&&gm.skillPoints==oldSkill+2,"Levels +10 uses normal point rewards");
 Check(gm.xpNow==0&&gm.xpMax>0&&view.status.text.Contains("Lv."+gm.playerLevel),"Experience and displayed level refreshed");
 Check(view.levels.transform.GetSiblingIndex()<view.points.transform.GetSiblingIndex()&&((RectTransform)view.levels.transform).anchoredPosition.x<((RectTransform)view.points.transform).anchoredPosition.x,"Level button is first at top left");
 gm.playerLevel=LevelDataDescriptions.ExpLevelDb.Length-1;view.levels.onClick.Invoke();
 Check(gm.playerLevel==LevelDataDescriptions.ExpLevelDb.Length+9&&gm.xpMax==LevelDataDescriptions.ExpLevelDb[LevelDataDescriptions.ExpLevelDb.Length-1],"Level increase handles XP table boundary");
 int stat=gm.statPoints,skill=gm.skillPoints;view.points.onClick.Invoke();Check(gm.statPoints==stat+10&&gm.skillPoints==skill+10,"Grant points");gm.statPoints=stat;gm.skillPoints=skill;view.fast.onClick.Invoke();yield return null;Check(Time.timeScale==2&&!view.fast.interactable,"Double speed and disabled state");view.normal.onClick.Invoke();Check(Time.timeScale==1,"Restore speed without chest lookup");view.reset.onClick.Invoke();Check(view.confirmation.activeSelf,"Reset requires confirmation");view.cancelReset.onClick.Invoke();Check(!view.confirmation.activeSelf,"Reset cancellation");debug.Close();Check(!debug.m_ShowDebug,"Close hides overlay");gc.homeUI.settingsButton.onClick.Invoke();ui.developer.onClick.Invoke();Check(debug.m_ShowDebug&&!ui.IsOpen,"Settings entry opens floating overlay");var drag=view.GetComponentInChildren<DeveloperOverlayDrag>();drag.OnDrag(new PointerEventData(EventSystem.current){delta=new Vector2(-100000,100000)});yield return null;Check(view.panel.anchoredPosition.x>=0&&view.panel.anchoredPosition.y<=0,"Drag clamps at safe screen edge");Router.single.MapButton();yield return new WaitForSecondsRealtime(3);Check(debug.m_ShowDebug&&GameManager.single.gameState==Assets.Scripts.Game.Enum.GameStateType.MAP,"Overlay persists above map navigation");debug.Close();
 StorybookEquipmentValidation.Resolution(1080,1920);File.AppendAllText(Out+"validation.txt","DONE\n");EditorApplication.isPlaying=false;}
}
